lib = '''
def cells(grid, color):
    """All positions of a color as (row, col) tuples."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]

def bbox(pos):
    """(min_row, min_col, max_row, max_col) of a list of positions."""
    rs = [p[0] for p in pos]; cs = [p[1] for p in pos]
    return min(rs), min(cs), max(rs), max(cs)

def full_line(grid, index, axis):
    """Grid with row (axis='row') or column (axis='col') `index` set to 8."""
    g = [row[:] for row in grid]
    if axis == 'col':
        for row in g: row[index] = 8
    else:
        g[index] = [8] * len(g[index])
    return g

def divider_line(grid, color=2):
    """(axis, index) of the full line of `color` dividing the grid; None if absent."""
    h, w = len(grid), len(grid[0])
    for j in range(w):
        if all(grid[i][j] == color for i in range(h)): return ('col', j)
    for i in range(h):
        if all(v == color for v in grid[i]): return ('row', i)
    return None

def echo_line(grid, color=2, new=8):
    """Draw a full line of `new` just beyond the object (any non-background,
    non-divider color) on its far side from the divider line of `color`,
    if the object's extent in that direction fits in the space there."""
    div = divider_line(grid, color)
    if div is None: return grid
    axis, di = div
    bg = max({v for row in grid for v in row} - {color}, key=lambda c: sum(r.count(c) for r in grid))
    pos = [p for p in cells(grid, bg)]
    if not pos: return grid
    r0, c0, r1, c1 = bbox(pos)
    if axis == 'col':
        lo, hi = c1 + 1, c0 - 1   # candidate line index on the far side of the divider
        if di < c0:   idx, space, extent = hi, c0, c1 - c0 + 1
        else:         idx, space, extent = lo, len(grid[0]) - 1 - c1, c1 - c0 + 1
        if space >= extent: return full_line(grid, idx, 'col')
    else:
        if di < r0:   idx, space, extent = r0 - 1, r0, r1 - r0 + 1
        else:         idx, space, extent = r1 + 1, len(grid) - 1 - r1, r1 - r0 + 1
        if space >= extent: return full_line(grid, idx, 'row')
    return grid
'''
